public class Main {
    public static void main(String[] args) {
        // Pipeline 1: supply -> append -> uppercase -> print -> notify
        CompletableFuture.supplyAsync(() -> "Arcane")
            // TODO: thenApply to append " Surge"
            // TODO: thenApply to convert to uppercase
            // TODO: thenAccept to print "Final spell: " + result
            // TODO: thenRun to print "Pipeline complete"
